\set ON_ERROR_STOP on
BEGIN;
DO $vedu_wave_2$
DECLARE
  spec jsonb;
  qspec jsonb;
  v_lesson bigint;
  v_quiz bigint;
  v_question bigint;
  v_answer bigint;
  v_attempts integer;
