  v_i integer;
  v_j integer;
BEGIN
  FOR spec IN SELECT value FROM jsonb_array_elements($BANK_JSON$[{"course":45,"course_name":"Học sâu","order":2,"expected_lesson":"01 · Tổng quan","questions":[{"text":"Deep learning thuộc nhóm phương pháp nào?","options":["Cơ sở dữ liệu quan hệ","Thuật toán nén không mất dữ liệu","Học máy sử dụng mạng nơron nhiều tầng","Giao thức mạng"],"correct":2},{"text":"Trong học có giám sát, nhãn của mẫu huấn luyện là gì?","options":["Đầu ra mong muốn của mẫu","Số tham số của CPU","Tốc độ ổ cứng","Tên file bất kỳ"],"correct":0},{"text":"Tập test nên được sử dụng vào giai đoạn nào?","options":["Học trọng số sau mỗi batch","Đánh giá cuối cùng sau khi chọn mô hình","Điều chỉnh siêu tham số liên tục","Tính gradient cho optimizer"],"correct":1},{"text":"Tập validation chủ yếu dùng để làm gì?","options":["Đóng vai nhãn giả","Chọn cấu hình và theo dõi khả năng tổng quát","Lưu file ảnh gốc","Thay toàn bộ dữ liệu train"],"correct":1},{"text":"Với 1.000 ảnh chia 70/15/15, tập train có bao nhiêu ảnh?","options":["700","150","850","70"],"correct":0},{"text":"Với 1.000 ảnh chia 70/15/15, tập test có bao nhiêu ảnh?","options":["15","700","150","300"],"correct":2},{"text":"Dữ liệu từ cùng một người nên được chia train/test theo cách nào để tránh rò rỉ?","options":["Chỉ chia theo kích thước ảnh","Tách theo người thay vì tách ngẫu nhiên từng ảnh","Lặp ảnh trên hai tập","Trộn cả nhãn test vào train"],"correct":1},{"text":"Baseline trong thực nghiệm dùng để làm gì?","options":["Tăng số lớp mạng bắt buộc","Thay thế thước đo đánh giá","Mã hóa dữ liệu ảnh","Làm mốc so sánh kết quả mô hình mới"],"correct":3},{"text":"Ví dụ nhiệm vụ nào là phân loại ảnh?","options":["Dự đoán chính xác dung lượng RAM","Nén ZIP bằng mật khẩu","Xác định ảnh thuộc loại sản phẩm A hay B","Sắp xếp IP theo địa chỉ"],"correct":2},{"text":"Overfitting biểu hiện rõ nhất khi nào?","options":["Train và validation đều ổn định tốt","Số epoch bằng một","Kết quả train tốt nhưng kết quả trên dữ liệu chưa thấy kém","Không có dữ liệu train"],"correct":2}]},{"course":45,"course_name":"Học sâu","order":3,"expected_lesson":"02 · ANN và lan truyền ngược","questions":[{"text":"Neuron tuyến tính tính giá trị trước kích hoạt như thế nào?","options":["Tổng có trọng số của đầu vào cộng bias","Trung bình thời gian train","Tổng số hàng trong dataset","Tích các nhãn của lớp"],"correct":0},{"text":"Sigmoid tại đầu vào bằng 0 có giá trị bao nhiêu?","options":["0","0,5","-1","1"],"correct":1},{"text":"Vai trò của hàm kích hoạt phi tuyến trong MLP là gì?","options":["Cho phép mạng biểu diễn quan hệ phi tuyến","Thay phép lan truyền ngược","Giảm số mẫu dữ liệu về 0","Đảm bảo không bao giờ overfit"],"correct":0},{"text":"Lan truyền ngược dùng chủ yếu để làm gì?","options":["Tính gradient của loss theo tham số","Chia dữ liệu train/test","Tìm địa chỉ IP","Mã hóa tệp mô hình"],"correct":0},{"text":"Quy tắc đạo hàm chuỗi được dùng trong backpropagation vì sao?","options":["Gradient phải đi qua nhiều phép biến đổi liên tiếp","Tất cả tham số luôn bằng 1","Không tồn tại hàm loss","Mạng không có lớp ẩn"],"correct":0},{"text":"MLP 2→3→1 có bias mỗi neuron có bao nhiêu tham số?","options":["10","13","9","6"],"correct":1},{"text":"Tại sao một perceptron tuyến tính đơn không giải quyết được XOR?","options":["XOR không có nhãn","XOR không phân tách tuyến tính trong không gian đầu vào","XOR luôn chỉ có một mẫu","Không thể dùng số nhị phân"],"correct":1},{"text":"Gradient descent điều chỉnh trọng số theo hướng nào?","options":["Theo giá trị nhãn test","Ngược chiều gradient của hàm mất mát","Cùng chiều gradient với bước vô hạn","Theo thứ tự chữ cái"],"correct":1},{"text":"Với w=2, gradient=0,3 và learning rate=0,1, giá trị w sau SGD là bao nhiêu?","options":["1,70","2,03","2,30","1,97"],"correct":3},{"text":"Kiểm tra gradient bằng sai phân trung tâm giúp làm gì?","options":["Tăng nhãn huấn luyện","Loại bỏ dữ liệu validation","Đối chiếu gradient tính tay/autograd với xấp xỉ số","Chọn ngẫu nhiên lớp đầu ra"],"correct":2}]},{"course":45,"course_name":"Học sâu","order":4,"expected_lesson":"03 · Huấn luyện mạng nơron","questions":[{"text":"Training loss giảm nhưng validation loss tăng thường là dấu hiệu gì?","options":["Dữ liệu test hoàn hảo","Batch size bằng 0","Underflow mạng","Overfitting"],"correct":3},{"text":"Early stopping nên theo dõi dữ liệu nào?","options":["Validation","Mã định danh file","Test dùng để báo cáo cuối","Nhãn không tồn tại"],"correct":0},{"text":"Learning rate quá lớn có thể gây điều gì?","options":["Không cần gradient","Luôn giảm loss đều","Dao động hoặc không hội tụ","Mọi mô hình đều tối ưu"],"correct":2},{"text":"Batch size là gì?","options":["Số cột trong file JSON","Số người dùng đăng nhập","Số lớp trong mạng","Số mẫu dùng trong một lần cập nhật gradient"],"correct":3},{"text":"Epoch là gì?","options":["Một lần chạy kiểm thử ngoài mạng","Một lượt huấn luyện qua toàn bộ tập train","Một phép đo accuracy duy nhất","Một tham số của ảnh"],"correct":1},{"text":"Regularization nhằm mục tiêu chính nào?","options":["Hạn chế quá khớp và cải thiện tổng quát","Tạo thêm nhãn test","Tăng số chiều không giới hạn","Buộc train loss bằng 0"],"correct":0},{"text":"Để so sánh SGD và Adam công bằng cần làm gì?","options":["Giữ cùng split, ngân sách và kiểm soát seed","Thay metric giữa hai mô hình","Dùng dữ liệu khác nhau không ghi nhận","Cho Adam xem tập test trước"],"correct":0},{"text":"Data augmentation cho ảnh train có tác dụng gì?","options":["Đưa ảnh test vào train","Cắt bỏ tập validation","Tăng đa dạng biến thể đầu vào phù hợp nhãn","Thay nhãn của mọi ảnh thành giống nhau"],"correct":2},{"text":"Ablation study nhằm mục đích gì?","options":["Thay số liệu đo bằng ước lượng","Đo đóng góp của từng thành phần bằng cách bỏ/thay một yếu tố","Bỏ báo cáo baseline","Chỉ đổi tên mô hình"],"correct":1},{"text":"Khi chọn siêu tham số, vì sao không tối ưu trực tiếp trên test?","options":["Tránh rò rỉ thông tin và thiên lệch đánh giá cuối cùng","Vì test luôn có gradient lớn hơn","Vì test không thể lưu ra CSV","Vì test không có dữ liệu"],"correct":0}]},{"course":45,"course_name":"Học sâu","order":5,"expected_lesson":"04 · CNN và ResNet","questions":[{"text":"Lớp convolution thường dùng để khai thác đặc điểm nào của ảnh?","options":["Mẫu cục bộ trong không gian","Mật khẩu người dùng","Số lượt đăng nhập","Tên đường dẫn của tệp"],"correct":0},{"text":"Kernel kích thước 3×3 trên ảnh 32×32 với stride 1, padding valid cho kích thước không gian đầu ra nào?","options":["34×34","32×32","16×16","30×30"],"correct":3},{"text":"Convolution có 16 filter 3×3 với đầu vào 3 kênh và bias thì có bao nhiêu tham số?","options":["144","432","448","160"],"correct":2},{"text":"Max pooling 2×2 stride 2 áp lên tensor 30×30×16 tạo shape nào?","options":["30×30×8","60×60×16","15×15×16","15×15×8"],"correct":2},{"text":"Vai trò thường gặp của pooling trong CNN là gì?","options":["Tạo câu hỏi quiz","Thay optimizer","Giảm kích thước không gian đặc trưng","Tăng nhãn dữ liệu"],"correct":2},{"text":"Trong residual block, shortcut y=F(x)+x yêu cầu gì khi cộng trực tiếp?","options":["Hai tensor phải cùng shape hoặc được chiếu tương thích","Hai tensor có tên giống nhau","Số lớp mạng phải là 1","Mọi phần tử bắt buộc bằng 0"],"correct":0},{"text":"Khi kích thước đầu vào và nhánh residual khác nhau, thường dùng gì trên shortcut?","options":["Bỏ toàn bộ dữ liệu","Đổi tên file","Projection 1×1 thích hợp","Tăng batch size đến vô hạn"],"correct":2},{"text":"ResNet sử dụng skip connection để hỗ trợ điều gì?","options":["Thay thế nhãn dữ liệu","Loại bỏ mọi phép convolution","Truyền tín hiệu/gradient qua mạng sâu","Tính trực tiếp độ chính xác test"],"correct":2},{"text":"Stride của convolution ảnh hưởng trực tiếp đến điều gì?","options":["Bước di chuyển kernel và kích thước đầu ra","Số lượng lớp nhãn","Số tên người dùng","Số file PDF"],"correct":0},{"text":"CNN dùng cùng kernel tại nhiều vị trí thể hiện tính chất gì?","options":["Không học tham số","Mỗi pixel có một kernel hoàn toàn riêng","Chia sẻ trọng số theo không gian","Bắt buộc chỉ dùng một kênh"],"correct":2}]},{"course":45,"course_name":"Học sâu","order":6,"expected_lesson":"05 · RNN, BPTT, LSTM và GRU","questions":[{"text":"RNN phù hợp với dữ liệu có đặc trưng nào?","options":["Không có quan hệ thứ tự","Chỉ bảng lưu mật khẩu","Có thứ tự theo thời gian hoặc chuỗi","Chỉ ảnh tĩnh đơn lẻ"],"correct":2},{"text":"Ở RNN cơ bản, trọng số được sử dụng giữa các bước thời gian như thế nào?","options":["Dùng chung qua các bước","Không có trọng số","Mỗi bước luôn là mô hình độc lập hoàn toàn","Chỉ cập nhật ở test"],"correct":0},{"text":"BPTT là viết tắt của kỹ thuật nào?","options":["Lan truyền ngược qua thời gian","Chuyển ảnh sang PDF","Đánh giá không cần nhãn","Tách batch theo tên"],"correct":0},{"text":"Vấn đề thường gặp khi huấn luyện RNN chuỗi dài là gì?","options":["Không tồn tại hidden state","Gradient biến mất hoặc bùng nổ","Không thể dùng dữ liệu số","Không thể tạo tensor"],"correct":1},{"text":"LSTM sử dụng cell state chủ yếu để làm gì?","options":["Hỗ trợ duy trì thông tin qua nhiều bước","Làm hàm loss tự động bằng 0","Lưu trực tiếp file CSV","Thay toàn bộ dữ liệu đầu vào"],"correct":0},{"text":"GRU thường có số trạng thái chính nào so với LSTM chuẩn?","options":["Có hai cell state độc lập bắt buộc","Không có cell state riêng giống LSTM","Có ba cell state cho mỗi neuron","Không có hidden state"],"correct":1},{"text":"Cửa sổ đầu vào 10 quan sát để dự báo một bước nghĩa là gì?","options":["Dự đoán đồng thời 10 nhãn test","Dùng 10 giá trị quá khứ để dự đoán giá trị kế tiếp","Dùng 10 giá trị tương lai làm đầu vào","Xóa mọi giá trị quá khứ"],"correct":1},{"text":"Khi đánh giá chuỗi thời gian nên chia train/test theo cách nào?","options":["Giữ đúng một mẫu train","Trộn ngẫu nhiên từng bước không quan tâm thời gian","Theo mốc thời gian để hạn chế nhìn trước tương lai","Dùng test làm train"],"correct":2},{"text":"Bộ chuẩn hóa cho bài toán chuỗi nên fit dựa trên dữ liệu nào?","options":["Toàn bộ chuỗi kể cả test","Chỉ tập test","Chỉ tập train","Các nhãn dự đoán tương lai"],"correct":2},{"text":"MAE của mô hình dự báo thể hiện điều gì?","options":["Trung bình trị tuyệt đối sai số dự đoán","Tổng số lớp của mạng","Bình phương của recall","Số lượng file được lưu"],"correct":0}]},{"course":46,"course_name":"Khai phá dữ liệu","order":2,"expected_lesson":"01 · Tổng quan và tiền xử lý","questions":[{"text":"Mục tiêu chính của bước làm sạch dữ liệu là gì?","options":["Tăng kích thước mô hình","Chuyển mọi nhãn thành 1","Xử lý thiếu, sai và dữ liệu không nhất quán","Chỉ đổi font chữ"],"correct":2},{"text":"Phân lớp dự đoán loại đầu ra nào?","options":["Hệ số nén","Tổng số byte trong file","Một cây thư mục","Nhãn rời rạc"],"correct":3},{"text":"Hồi quy thường dự đoán đầu ra nào?","options":["Giá trị số liên tục","Danh sách quyền truy cập","Kiểu tên tập tin","Màu giao diện bắt buộc"],"correct":0},{"text":"Gom cụm khác phân lớp ở điểm quan trọng nào?","options":["Không cần nhãn lớp đã biết để hình thành nhóm","Chỉ dùng dữ liệu văn bản","Luôn dùng nhãn đúng cho từng mẫu","Chỉ áp dụng cho một quan sát"],"correct":0},{"text":"Luật kết hợp nhằm tìm gì?","options":["Địa chỉ IP của máy chủ","Quan hệ thường xuất hiện cùng nhau giữa các mục","Thứ tự xuất hiện của mã nguồn","Độ phân giải ảnh"],"correct":1},{"text":"Dữ liệu tuổi 20,22,thiếu,26; điền thiếu bằng trung bình quan sát được là bao nhiêu?","options":["24","20","26","22,67"],"correct":3},{"text":"Min-max scaling về [0,1] của giá trị nhỏ nhất có kết quả nào?","options":["1","-1","0","0,5"],"correct":2},{"text":"Khi train mô hình, thống kê để điền thiếu nên tính trên tập nào?","options":["Tập train","Cả train và test gộp","Chỉ mẫu được dự đoán sau này","Tập test trước"],"correct":0},{"text":"Ví dụ rò rỉ dữ liệu là gì?","options":["Dùng tuổi có sẵn trước thời điểm dự đoán","Không sử dụng nhãn của test để train","Chia dữ liệu theo thời gian","Dùng kết quả chỉ biết sau thời điểm dự đoán làm đầu vào"],"correct":3},{"text":"KDD bao gồm bước nào bên cạnh lựa chọn và tiền xử lý dữ liệu?","options":["Xóa hệ thống sau khi đánh giá","Đổi tên database","Tăng độ sáng màn hình","Khai phá mẫu và diễn giải đánh giá kết quả"],"correct":3}]},{"course":46,"course_name":"Khai phá dữ liệu","order":3,"expected_lesson":"02 · Tập phổ biến và luật kết hợp","questions":[{"text":"Support của luật A→B là gì?","options":["Số nhóm K-means","Tỷ lệ giao dịch chỉ chứa B","Tỷ lệ giao dịch chỉ chứa A","Tỷ lệ giao dịch chứa cả A và B"],"correct":3},{"text":"Confidence của luật A→B được tính như thế nào?","options":["Số giao dịch chia số mặt hàng","Support(B)/Support(A∪B)","Support(A)/Support(B)","Support(A∪B)/Support(A)"],"correct":3},{"text":"Lift của luật A→B là gì?","options":["Support(B)/Confidence(A→B)","Confidence(A→B)/Support(B)","Support(A∪B) nhân tổng số dòng","Support(A)/Support(B)"],"correct":1},{"text":"Trong 5 giao dịch có 3 giao dịch chứa A và B, support(A,B) bằng bao nhiêu?","options":["60%","5%","3%","30%"],"correct":0},{"text":"Với 8 giao dịch và minsup 30%, tập mục cần xuất hiện tối thiểu mấy lần?","options":["1","2","4","3"],"correct":3},{"text":"Tập mục phổ biến tối đại có tính chất nào?","options":["Không có tập con nào phổ biến","Chỉ có một phần tử","Luôn có support bằng 100%","Không có siêu tập thực sự nào cũng phổ biến"],"correct":3},{"text":"Tập mục phổ biến đóng được xác định bởi điều gì?","options":["Tập có support thấp nhất","Chỉ tập có 2 phần tử","Không có siêu tập thực sự nào có cùng support","Không có tập con nào cùng tên"],"correct":2},{"text":"Apriori dựa vào nguyên lý nào?","options":["Support tăng khi thêm mục","Mọi tập con của tập mục phổ biến cũng phổ biến","Không cần đếm giao dịch","Mọi siêu tập đều phổ biến"],"correct":1},{"text":"Trong luật kết hợp, confidence cao có bảo đảm nhân quả không?","options":["Không, quan hệ cùng xuất hiện không chứng minh nhân quả","Có nếu lift bằng 1","Có, luôn chứng minh nguyên nhân","Có nếu chỉ có 2 giao dịch"],"correct":0},{"text":"FP-tree thường nhằm mục đích gì?","options":["Mã hóa hình ảnh thành RGB","Nén cấu trúc giao dịch để khai phá tập phổ biến","Tìm đường đi ngắn nhất","Dự đoán nhãn bằng hồi quy tuyến tính"],"correct":1}]},{"course":46,"course_name":"Khai phá dữ liệu","order":4,"expected_lesson":"03 · Phân lớp dữ liệu","questions":[{"text":"Entropy của tập nhãn 50% Có, 50% Không tính theo log2 là bao nhiêu?","options":["2 bit","1 bit","0,5 bit","0 bit"],"correct":1},{"text":"Information gain của thuộc tính làm hai nhánh thuần từ tập cân bằng là bao nhiêu?","options":["1 bit","0,5 bit","0 bit","2 bit"],"correct":0},{"text":"KNN phân lớp mẫu mới bằng nguyên tắc nào?","options":["Dựa trên nhãn của các láng giềng gần nhất","Luôn chọn lớp hiếm nhất","Không cần dữ liệu huấn luyện","Chỉ dùng tham số bias"],"correct":0},{"text":"Trong KNN, vì sao nên chuẩn hóa đặc trưng khác thang đo?","options":["Tránh đặc trưng có thang lớn chi phối khoảng cách","Tự tạo thêm điểm dữ liệu","Tăng số nhãn vô hạn","Thay khoảng cách bằng tên người dùng"],"correct":0},{"text":"Precision được tính bằng công thức nào?","options":["TN/(TN+FP)","TP/(TP+TN)","TP/(TP+FN)","TP/(TP+FP)"],"correct":3},{"text":"Recall được tính bằng công thức nào?","options":["TP/(TP+FP)","TN/(TN+FP)","TP/(TP+FN)","FP/(FP+TN)"],"correct":2},{"text":"F1-score là gì?","options":["Hệ số tương quan Pearson","Trung bình số lượng cột","Số hàng validation","Trung bình điều hòa của precision và recall"],"correct":3},{"text":"Naive Bayes dựa trên giả định thường gặp nào?","options":["Mọi biến phải là số nguyên","Tất cả lớp có số mẫu bằng nhau","Các thuộc tính độc lập có điều kiện theo lớp","Không có xác suất"],"correct":2},{"text":"Cây quyết định thường chia nhánh nhằm mục tiêu gì?","options":["Thay tất cả đặc trưng thành tên lớp","Giảm số hàng về 0","Tăng độ thuần của nhãn trong các nhóm","Chuyển dữ liệu thành ảnh"],"correct":2},{"text":"Với TP=18, FP=6, FN=2, TN=24, accuracy bằng bao nhiêu?","options":["84%","72%","75%","90%"],"correct":0}]},{"course":46,"course_name":"Khai phá dữ liệu","order":5,"expected_lesson":"04 · Gom cụm dữ liệu","questions":[{"text":"K-means yêu cầu chỉ định tham số nào từ đầu?","options":["Loại GPU bắt buộc","Mật khẩu dữ liệu","Số nhãn có giám sát","Số cụm k"],"correct":3},{"text":"Tâm cụm trong K-means thường được cập nhật bằng gì?","options":["Giá trị nhãn biết trước","Điểm xa nhất trong cụm","Tên dữ liệu gần nhất","Trung bình các điểm thuộc cụm"],"correct":3},{"text":"Với điểm 1D 1 và 2 được gán chung cụm, tâm mới là gì?","options":["2","1,5","3","1"],"correct":1},{"text":"SSE trong gom cụm thường đo điều gì?","options":["Tỷ lệ chính xác phân lớp","Số lớp trong mạng CNN","Số câu hỏi quiz","Tổng bình phương khoảng cách từ điểm đến tâm cụm"],"correct":3},{"text":"Tăng k thường khiến SSE trên cùng dữ liệu có xu hướng nào?","options":["Luôn tăng lên","Bằng tổng số hàng","Không thể tính","Không tăng tại nghiệm tối ưu"],"correct":3},{"text":"Một hạn chế của K-means là gì?","options":["Luôn tìm được nhãn đúng","Không có bước gán cụm","Nhạy cảm với điểm ngoại lai và tâm khởi tạo","Không dùng được số thực"],"correct":2},{"text":"K-medoids khác K-means ở điểm nào?","options":["Tâm đại diện là một điểm dữ liệu thực","Tâm luôn là trung bình số học","Chỉ dùng cho dữ liệu có nhãn","Không sử dụng khoảng cách"],"correct":0},{"text":"Gom cụm phân cấp thường tạo ra cấu trúc nào?","options":["Ma trận nhãn đúng","Bảng chân trị logic","Mạng tích chập","Cây phân cấp các cụm"],"correct":3},{"text":"Vì sao cần chuẩn hóa trước khi gom cụm theo khoảng cách?","options":["Loại bỏ toàn bộ nhiễu","Tránh biến có thang đo lớn áp đảo khoảng cách","Tạo ra giá trị p","Đảm bảo mọi nhãn bằng nhau"],"correct":1},{"text":"Điểm ngoại lai (30,30) thêm vào nhóm quanh (1,1) ảnh hưởng K-means thế nào?","options":["Không thể ảnh hưởng tâm","Luôn xóa cụm","Bắt buộc giảm số k","Có thể kéo tâm cụm lệch mạnh"],"correct":3}]},{"course":46,"course_name":"Khai phá dữ liệu","order":6,"expected_lesson":"05 · Tương quan, kiểm định và hồi quy","questions":[{"text":"Pearson r đo chủ yếu điều gì?","options":["Quan hệ nhân quả chắc chắn","Số dòng trong file","Số lớp neural network","Mức độ và chiều của liên hệ tuyến tính giữa hai biến số"],"correct":3},{"text":"Với y=2x cho x=[1,2,3], hệ số tương quan Pearson r bằng bao nhiêu?","options":["0","-1","2","1"],"correct":3},{"text":"Với x=[1,2,3], y=[2,4,6], hệ số góc hồi quy tuyến tính là bao nhiêu?","options":["1","6","0","2"],"correct":3},{"text":"Tương quan cao có chứng minh quan hệ nhân quả không?","options":["Có khi r âm","Có trong mọi trường hợp","Không","Có khi p-value lớn"],"correct":2},{"text":"Kiểm định chi-square độc lập thường dùng để làm gì?","options":["Xác định cỡ file","Ước lượng trọng số CNN","Tính khoảng cách Euclid","Đánh giá liên hệ giữa hai biến phân loại"],"correct":3},{"text":"ANOVA một yếu tố thường dùng để so sánh gì?","options":["Độ sâu của cây tìm kiếm","Số cạnh của đồ thị","Trung bình của từ ba nhóm trở lên","Tỷ lệ nén của tập tin"],"correct":2},{"text":"Giả thuyết H0 thường đại diện cho điều gì?","options":["Giả thuyết không có hiệu ứng hoặc khác biệt theo thiết kế kiểm định","Kết quả luôn đúng","Tập validation","Đáp án được chọn nhiều nhất"],"correct":0},{"text":"P-value nhỏ hơn mức ý nghĩa 0,05 thường dẫn tới quyết định nào?","options":["Chấp nhận H0 chắc chắn đúng","Kết luận hiệu ứng lớn","Chứng minh nhân quả","Bác bỏ H0 theo quy tắc kiểm định"],"correct":3},{"text":"Hồi quy logistic nhị phân thường mô hình hóa loại đầu ra nào?","options":["Số lượng cụm không giám sát","Giá trị RGB trực tiếp","Xác suất thuộc lớp nhị phân","Bảng định tuyến"],"correct":2},{"text":"Đặc trưng đa cộng tuyến mạnh có thể gây vấn đề gì khi diễn giải hồi quy tuyến tính?","options":["Làm biến độc lập biến mất","Giảm mọi sai số xuống 0","Hệ số ước lượng kém ổn định và khó diễn giải","Bắt buộc tạo 100 nhãn"],"correct":2}]}]$BANK_JSON$::jsonb)
  LOOP
    SELECT l.lesson_id INTO STRICT v_lesson
    FROM lms.lessons l JOIN lms.courses c ON c.course_id=l.course_id
    WHERE c.course_name=spec->>'course_name'
      AND c.course_id=(spec->>'course')::bigint
      AND l.lesson_order=(spec->>'order')::int
      AND l.is_published=true AND l.is_deleted=false
      AND l.title=spec->>'expected_lesson';
    SELECT q.quiz_id INTO STRICT v_quiz
    FROM assessment.quizzes q
    WHERE q.course_id=(spec->>'course')::bigint AND q.lesson_id=v_lesson
      AND q.is_published=true AND q.is_deleted=false;
    SELECT count(*) INTO v_old_count FROM assessment.questions WHERE quiz_id=v_quiz;
    IF v_old_count NOT IN (3,10) THEN
      RAISE EXCEPTION 'Quiz % has unexpected question count %',v_quiz,v_old_count;
    END IF;
    SELECT count(*) INTO v_attempts FROM assessment.quiz_attempts WHERE quiz_id=v_quiz;
    IF v_old_count=3 THEN
      IF v_attempts=0 THEN
        -- Reuse question and answer IDs to avoid orphaning existing references.
        FOR v_i IN 1..3 LOOP
          qspec:=spec->'questions'->(v_i-1);
          SELECT question_id INTO STRICT v_question FROM assessment.questions
          WHERE quiz_id=v_quiz AND question_order=v_i;
          IF (SELECT count(*) FROM assessment.answers WHERE question_id=v_question) <> 4 THEN
            RAISE EXCEPTION 'Quiz %, question % not exactly four options',v_quiz,v_question;
          END IF;
          UPDATE assessment.questions
          SET question_text=qspec->>'text', question_type='SINGLE_CHOICE', points=1
          WHERE question_id=v_question;
          FOR v_j IN 1..4 LOOP
            SELECT answer_id INTO STRICT v_answer FROM assessment.answers
            WHERE question_id=v_question AND answer_order=v_j;
            UPDATE assessment.answers
            SET answer_text=qspec->'options'->>(v_j-1),
                is_correct=((qspec->>'correct')::int=v_j-1)
            WHERE answer_id=v_answer;
          END LOOP;
        END LOOP;
      ELSE
        RAISE NOTICE 'Quiz % retains three original questions (% existing attempts); inspect topical relevance',v_quiz,v_attempts;
      END IF;
      FOR v_i IN 4..10 LOOP
        qspec:=spec->'questions'->(v_i-1);
        INSERT INTO assessment.questions(quiz_id,question_text,question_type,question_order,points)
        VALUES(v_quiz,qspec->>'text','SINGLE_CHOICE',v_i,1)
        RETURNING question_id INTO v_question;
        FOR v_j IN 1..4 LOOP
          INSERT INTO assessment.answers(question_id,answer_text,is_correct,answer_order)
          VALUES(v_question,qspec->'options'->>(v_j-1),
            ((qspec->>'correct')::int=v_j-1),v_j);
        END LOOP;
      END LOOP;
    ELSE
      -- Fail rather than silently overwriting another migration.
      FOR v_i IN 4..10 LOOP
        qspec:=spec->'questions'->(v_i-1);
        IF NOT EXISTS(SELECT 1 FROM assessment.questions
          WHERE quiz_id=v_quiz AND question_order=v_i
            AND question_text=qspec->>'text') THEN
          RAISE EXCEPTION 'Quiz % differs at question %; aborting',v_quiz,v_i;
        END IF;
      END LOOP;
    END IF;
    UPDATE assessment.quizzes SET updated_at=now(),
      time_limit_seconds=GREATEST(COALESCE(time_limit_seconds,0),900)
      WHERE quiz_id=v_quiz;
  END LOOP;
END;
$vedu_wave_2$;
COMMIT;
